  # are allowed and used, the transport timeout, the monotonic deadline of the
  # whole call (:unset until the first request is built, so the time spent
  # fetching a token is not charged to the call; nil when there is no timeout)
  # and whether the one 401 replay was spent.
  @typep attempt_state :: %{
           max_retries: non_neg_integer(),
           retries: non_neg_integer(),
           call_timeout: pos_integer() | nil,
           timeout: integer() | nil,
           deadline: integer() | nil | :unset,
           replayed: boolean()
         }

  @months %{
    "jan" => 1,
    "feb" => 2,
    "mar" => 3,
    "apr" => 4,
    "may" => 5,
    "jun" => 6,
    "jul" => 7,
    "aug" => 8,
    "sep" => 9,
    "oct" => 10,
    "nov" => 11,
    "dec" => 12
  }

  # Sends the request built by `build_request` and answers with `{:ok, response}`
  # or `{:error, exception}`.
  #
  # A 401 on a call authenticated by an OAuth2 or OpenID Connect authenticator
  # drops the cached access token (the refresh token stays) and replays the
  # request once, rebuilt, so it carries a fresh token; a second 401 is
  # returned as it is. Independently, a network error that happened before any
  # response, and the statuses 408, 409, 429 and 500 to 599 (not 501), are
  # retried up to `TransportOptions.max_retries` times with backoff. Neither
  # happens for a body that cannot be sent twice (a stream), and a retry never
  # waits past the end-to-end timeout.
  @spec send_with_retries(
          state(),
          atom(),
          term(),
          (:attempt | :replay -> {String.t(), map(), term()}),
          keyword()
        ) ::
          {:ok, term()} | {:error, Exception.t()}
  defp send_with_retries(state, method, effective_auth, build_request, call) do
    transport = transport_options(state.api_client)

    attempt(state, method, effective_auth, build_request, %{
      max_retries:
        Keyword.get_lazy(call, :max_retries, fn ->
          if(transport, do: transport.max_retries || 0, else: 0)
        end),
      retries: 0,
      call_timeout: Keyword.get(call, :timeout),
      timeout: Keyword.get(call, :timeout) || timeout(transport),
      deadline: :unset,
      replayed: false
    })
  end

  @spec attempt(
          state(),
          atom(),
          term(),
          (:attempt | :replay -> {String.t(), map(), term()}),
          attempt_state()
        ) ::
          {:ok, term()} | {:error, Exception.t()}
  defp attempt(state, method, effective_auth, build_request, ctx) do
    {url, headers, serialized_body} = build_request.(:attempt)
    ctx = if ctx.deadline == :unset, do: %{ctx | deadline: deadline(ctx.timeout)}, else: ctx

    result =
      send_once(
        state.api_client,
        method,
        url,
        headers,
        serialized_body,
        {ctx.deadline, ctx.call_timeout}
      )

    cond do
      not replayable?(serialized_body) ->
        result

      not ctx.replayed and unauthorized?(result) and
          invalidate_access_token(effective_auth) == :ok ->
        # A failed re-authentication keeps the 401 it replaces, as in the other SDKs.
        case build_for_replay(build_request) do
          {:ok, request} ->
            attempt(state, method, effective_auth, fn _mode -> request end, %{
              ctx
              | replayed: true
            })

          :error ->
            result
        end

      true ->
        case next_delay(result, method, ctx) do
          {:ok, delay} ->
            Process.sleep(delay)

            attempt(state, method, effective_auth, build_request, %{
              ctx
              | retries: ctx.retries + 1
            })

          :none ->
            result
        end
    end
  end

  # Builds the request again for a replay. Only a credential that cannot be
  # obtained again counts as a failure here; anything else is raised as before.
  defp build_for_replay(build_request) do
    {:ok, build_request.(:replay)}
  rescue
    _ in [
      PetstoreClient.Errors.OAuth2ServerError,
      PetstoreClient.Errors.OAuth2TokenError,
      PetstoreClient.Errors.NetworkError
    ] ->
      :error
  end

  defp send_once(api_client, method, url, headers, body, {deadline, call_timeout}) do
    {:ok,
     case api_client do
       %{__struct__: mod} = client ->
         if deadline != nil and function_exported?(mod, :send_request, 6) do
           mod.send_request(
             client,
             method,
             url,
             headers,
             body,
             Enum.reject([deadline: deadline, timeout: call_timeout], fn {_key, value} ->
               is_nil(value)
             end)
           )
         else
           mod.send_request(client, method, url, headers, body)
         end

       mod when is_atom(mod) ->
         mod.send_request(method, url, headers, body)
     end}
  rescue
    e -> {:error, e}
  end

  # The client's transport settings, or nil for a client that has none (a
  # custom client, a module): such a client is never retried.
  defp transport_options(%{
         __struct__: _,
         transport_options: %PetstoreClient.TransportOptions{} = options
       }),
       do: options

  defp transport_options(_api_client), do: nil

  defp timeout(%PetstoreClient.TransportOptions{timeout: timeout}) when is_integer(timeout),
    do: timeout

  defp timeout(_transport), do: nil

  defp deadline(timeout) when is_integer(timeout),
    do: System.monotonic_time(:millisecond) + timeout

  defp deadline(nil), do: nil

  # A stream body is consumed by the first send; every other body is bytes.
  defp replayable?(body) when is_function(body), do: false
  defp replayable?(%_{}), do: false
  defp replayable?(_body), do: true

  defp unauthorized?({:ok, %{status_code: 401}}), do: true
  defp unauthorized?(_result), do: false

  # Drops the cached access token of an OAuth2 or OpenID Connect authenticator
  # so its next call fetches (or refreshes) a new one. Any other authenticator
  # (API key, basic, bearer, none) has nothing to refresh: `:unsupported`.
  defp invalidate_access_token(%{__struct__: mod} = auth) do
    if Code.ensure_loaded?(mod) and function_exported?(mod, :invalidate_access_token, 1) do
      _ = mod.invalidate_access_token(auth)
      :ok
    else
      :unsupported
    end
  end

  defp invalidate_access_token(_auth), do: :unsupported

  # How long to wait before the next retry, or :none when the result is not
  # worth retrying, the retries are used up, or the wait would end past the
  # end-to-end timeout.
  defp next_delay(_result, _method, %{retries: retries, max_retries: max_retries})
       when retries >= max_retries, do: :none

  defp next_delay(result, method, ctx) do
    case delay_for(result, method, ctx.retries + 1) do
      nil -> :none
      delay -> within_budget(delay, ctx.deadline)
    end
  end

  defp delay_for({:ok, %{status_code: status} = response}, _method, retry_number) do
    if retryable_status?(status) do
      retry_after_ms(Map.get(response, :headers), DateTime.utc_now()) ||
        backoff_delay(retry_number, :rand.uniform())
    end
  end

  # A connection that dropped before any response is retried only for a method
  # that is safe to send twice (RFC 9110 section 9.2.2, plus QUERY). A POST or
  # PATCH could apply its change twice, so it is sent once. A TLS or certificate
  # failure repeats on every attempt, so it is never retried.
  defp delay_for({:error, %PetstoreClient.Errors.NetworkError{} = error}, method, retry_number)
       when method in @idempotent_methods do
    if tls_failure?(error), do: nil, else: backoff_delay(retry_number, :rand.uniform())
  end

  defp delay_for(_result, _method, _retry_number), do: nil

  defp tls_failure?(%{cause: %{reason: {:tls_alert, _}}}), do: true
  defp tls_failure?(_error), do: false

  defp within_budget(delay, nil), do: {:ok, delay}

  defp within_budget(delay, deadline) when is_integer(deadline) do
    if System.monotonic_time(:millisecond) + delay < deadline, do: {:ok, delay}, else: :none
  end

  @doc false
  # The statuses worth a retry: a request timeout, a conflict, a rate limit and
  # a server error other than 501 (not implemented).
  @spec retryable_status?(integer()) :: boolean()
  def retryable_status?(status),
    do: status in [408, 409, 429] or (status >= 500 and status <= 599 and status != 501)

  @doc false
  # The wait before retry number `retry_number` (1 for the first retry): 0.5 s
  # doubling to 8 s, less up to 25% for a `jitter` between 0 and 1.
  @spec backoff_delay(pos_integer(), float()) :: non_neg_integer()
  def backoff_delay(retry_number, jitter) do
    base =
      min(@retry_base_delay_ms * Integer.pow(2, min(retry_number - 1, 10)), @retry_max_delay_ms)

    round(base * (1 - @retry_jitter * jitter))
  end

  @doc false
  # The wait a `Retry-After` header asks for in milliseconds (a number of
  # seconds or an HTTP date, never more than 60 s), or nil when the header is
  # absent or not understood.
  @spec retry_after_ms(term(), DateTime.t()) :: non_neg_integer() | nil
  def retry_after_ms(headers, now) when is_map(headers) do
    value =
      Enum.find_value(headers, fn {name, value} ->
        if String.downcase(to_string(name)) == "retry-after", do: value
      end)

    if is_binary(value), do: parse_retry_after(String.trim(value), now)
  end

  def retry_after_ms(_headers, _now), do: nil

  defp parse_retry_after(value, now) do
    if value =~ ~r/\A\d+\z/ do
      min(String.to_integer(value), div(@retry_after_cap_ms, 1000)) * 1000
    else
      case parse_http_date(value) do
        nil -> nil
        date -> min(max(DateTime.diff(date, now, :millisecond), 0), @retry_after_cap_ms)
      end
    end
  end

  # IMF-fixdate, the form HTTP servers send: "Sun, 06 Nov 1994 08:49:37 GMT".
  defp parse_http_date(value) do
    with [_, day, month, year, hour, minute, second] <-
           Regex.run(
             ~r/\A[A-Za-z]{3}, (\d{2}) ([A-Za-z]{3}) (\d{4}) (\d{2}):(\d{2}):(\d{2}) GMT\z/,
             value
           ),
         month when is_integer(month) <- Map.get(@months, String.downcase(month)),
         {:ok, naive} <-
           NaiveDateTime.new(
             String.to_integer(year),
             month,
             String.to_integer(day),
             String.to_integer(hour),
             String.to_integer(minute),
             String.to_integer(second)
           ) do
      DateTime.from_naive!(naive, "Etc/UTC")
    else
      _ -> nil
    end
  end

  # Decode a 2xx response body into the declared return type. A body that
  # does not match the declared schema is a contract violation and the
  # deserialize path RAISES a SerializationError (bad base64 / UUID / unknown
  # enum / missing required field / primitive type mismatch).
  # That raise is allowed to propagate: it surfaces through `invoke_api` as a
  # raised exception, while transport-level failures remain tagged
  # `{:error, _}` from the send try/rescue above. The success path returns
  # `{:ok, ApiResult}`.
  defp decode_success_body(response, return_type) do
    return_type = return_type_for_status(return_type, response.status_code)

    data =
      if return_type && response.body && response.body != "" do
        ct_header =
          Enum.find(response.headers, fn {k, _v} ->
            String.downcase(k) == "content-type"
          end)

        resp_content_type =
          case ct_header do
            {_k, v} -> v |> String.split(";") |> List.first() |> String.trim()
            nil -> nil
          end

        # When Content-Type is absent (nil) treat it as JSON.
        is_json =
          is_nil(resp_content_type) or
            PetstoreClient.HeaderSelector.json_mime?(resp_content_type)

        cond do
          is_json and return_type == "binary()" and json_document?(response.body) ->
            # A binary operation that also declares application/json (content
            # negotiation) answered with a JSON document: the caller gets its raw
            # bytes, never a decode error. A JSON string literal (format: byte)
            # still goes through the base64 path below.
            response.body

          is_json ->
            # A 2xx body that does not match the declared schema is a
            # contract violation; propagate the decode error to the
            # caller instead of silently substituting the raw body
            # string (which would yield type confusion). For a binary
            # return type (a top-level `format: byte` value carried as
            # application/json) the body is a JSON string literal of base64,
            # quotes included: deserialize/2 JSON-parses it first and the
            # "binary()" conversion then base64-decodes the inner string, so
            # the quoted literal is never base64-decoded directly.
            PetstoreClient.ObjectSerializer.deserialize(response.body, return_type)

          return_type == "binary()" ->
            # Binary operations declare `return_type = "binary()"`. The
            # transport base64-encodes non-text response bodies into the
            # `response.body` string, so decode it back to raw bytes
            # here. Fall back to the raw
            # body if it is not valid base64 (e.g. a test server that
            # writes raw bytes), never raising.
            case Base.decode64(response.body) do
              {:ok, decoded} -> decoded
              :error -> response.body
            end

          return_type in ["String", "String.t()"] and not text_content_type?(resp_content_type) ->
            # A string result under a binary content type is the decoded body:
            # the base64 text the transport carries never reaches the caller (D107).
            case Base.decode64(response.body) do
              {:ok, decoded} -> decoded
              :error -> response.body
            end

          return_type in ["String", "String.t()"] ->
            response.body

          true ->
            # A non-JSON success body on an operation that returns a model, a
            # list or any other non-text type cannot be decoded; returning the
            # raw string as that type would be type confusion.
            raise PetstoreClient.Errors.SerializationError,
              message:
                "Response Content-Type #{resp_content_type} is not JSON " <>
                  "and cannot be decoded as #{return_type}"
        end
      else
        nil
      end

    {:ok,
     %PetstoreClient.ApiResult{
       status_code: response.status_code,
       data: data,
       raw_body: response.body,
       headers: response.headers
     }}
  end

  # Text content types reach the caller as the body text; every other one is a binary
  # type whose body the transport carries as base64.
  defp text_content_type?(content_type) do
    String.starts_with?(content_type, "text/") or String.ends_with?(content_type, "xml") or
      String.contains?(content_type, "javascript")
  end

  # An operation with several 2xx responses carries one type per status: the one
  # the response arrived with, else the union itself (a 2xx no row names).
  defp return_type_for_status({union, rows}, status) do
    Enum.find_value(rows, union, fn {code, type} ->
      if success_status_matches?(code, status), do: type
    end)
  end

  defp return_type_for_status(return_type, _status), do: return_type

  defp success_status_matches?(code, status) do
    code == Integer.to_string(status) or
      (String.ends_with?(code, "XX") and
         String.first(code) == String.first(Integer.to_string(status)))
  end

  defp json_document?(body) do
    case String.trim_leading(body) do
      "{" <> _ -> true
      "[" <> _ -> true
      _ -> false
    end
  end

  @doc """
  Build a collection parameter string.

  ## Parameters

    * `param` - The list of values.
    * `format` - The collection format (`:csv`, `:ssv`, `:tsv`, `:pipes` or `:multi`).

  ## Returns

    The joined string, or the list itself for `:multi`.
  """
  @spec build_collection_param([term()], atom()) :: String.t() | [String.t()]
  def build_collection_param(param, format) do
    case format do
      :ssv -> Enum.join(param, " ")
      :tsv -> Enum.join(param, "\t")
      :pipes -> Enum.join(param, "|")
      :multi -> param
      _ -> Enum.join(param, ",")
    end
  end

  # A per-call authenticator never went through the client constructor, so an
  # OAuth2 or OpenID Connect one has no transport yet and would fail with
  # "ApiClient has not been injected". It is handed the client's transport
  # here, like the client-level authenticator is.
  defp inject_api_client(%{__struct__: mod} = auth, api_client) when is_map(api_client) do
    if function_exported?(mod, :set_api_client, 2) do
      mod.set_api_client(auth, api_client)
    else
      auth
    end
  end

  defp inject_api_client(auth, _api_client), do: auth

  # Resolve an authenticator's credentials for the given behaviour callback
  # (:auth_headers, :query_params, or :cookie_params). Authenticators are
  # PetstoreClient.Auth.Authenticator behaviours: the credential providers are
  # CALLBACK FUNCTIONS on the authenticator's module, not data fields on the
  # struct, so they are dispatched through `effective_auth.__struct__.<cb>/1`
  # (guarded by `function_exported?/3`, mirroring how `send_request` and the
  # client's `set_api_client` are invoked). Returns nil when there is no
  # authenticator or it does not implement the callback, so callers can skip
  # the merge entirely. Reading these as struct fields would silently drop the
  # credential — every real authenticator defstruct holds only its secret
  # material (e.g. [:host, :token]), never an :auth_headers key.
  defp auth_credentials(effective_auth, callback)
       when is_map(effective_auth) and is_atom(callback) do
    case effective_auth do
      %{__struct__: mod} ->
        # Real authenticators are behaviour structs: the credential providers
        # are CALLBACK FUNCTIONS on the module, dispatched via the struct's
        # module (guarded so a struct that doesn't implement the callback
        # simply contributes nothing).
        if function_exported?(mod, callback, 1) do
          apply(mod, callback, [effective_auth])
        else
          nil
        end

      plain_map ->
        # Plain-map fast-path: a map-shaped auth carries its credentials as
        # data fields keyed by the callback name (e.g. %{auth_headers: %{...}}).
        # Supported for lightweight/ad-hoc auth injection alongside the
        # behaviour-struct form above.
        Map.get(plain_map, callback)
    end
  end

  defp auth_credentials(_effective_auth, _callback), do: nil

  # Query parameters keep their declaration order: the operation hands over an
  # ordered list of `{name, value}` tuples (a map is also accepted and then
  # iterates in key order). Authenticator-contributed parameters are appended
  # after the operation's own and replace an operation parameter of the same
  # name, as a map merge would.
  defp merge_query_params(query_params, auth_params) do
    auth_pairs = Enum.to_list(auth_params)
    auth_names = Enum.map(auth_pairs, fn {name, _value} -> name end)

    Enum.reject(Enum.to_list(query_params), fn {name, _value} -> name in auth_names end) ++
      auth_pairs
  end

  defp build_query_string(query_params) do
    query_params
    |> Enum.flat_map(&query_string_pairs/1)
    |> Enum.join("&")
  end

  # Build the `key=value` pairs for one query parameter. OAS allowReserved: a
  # value wrapped by ValueSerializer.maybe_allow_reserved/2 keeps RFC 3986
  # reserved characters literal instead of percent-encoding them.
  defp query_string_pairs({k, wrapped}) do
    {allow_reserved, value} = unwrap_allow_reserved(wrapped)
    query_string_pairs(k, value, allow_reserved)
  end

  defp query_string_pairs(_k, value, _allow_reserved) when is_nil(value) or value == [], do: []

  # An exploded object parameter: one `name=value` pair per property.
  defp query_string_pairs(_k, {:exploded_object, pairs}, allow_reserved) do
    Enum.map(pairs, fn {name, value} ->
      "#{encode_query_component(name)}=#{encode_query_value(PetstoreClient.ObjectSerializer.to_query_value(value, nil), allow_reserved)}"
    end)
  end

  defp query_string_pairs(k, values, allow_reserved) when is_list(values) do
    encoded_key = encode_query_component(to_string(k))

    Enum.map(values, fn val ->
      "#{encoded_key}=#{encode_query_value(PetstoreClient.ObjectSerializer.to_query_value(val, nil), allow_reserved)}"
    end)
  end

  defp query_string_pairs(k, value, allow_reserved) do
    encoded_key = encode_query_component(to_string(k))

    [
      "#{encoded_key}=#{encode_query_value(PetstoreClient.ObjectSerializer.to_query_value(value, nil), allow_reserved)}"
    ]
  end

  # Unwrap a query value that ValueSerializer.maybe_allow_reserved/2 tagged for
  # reserved-character preservation, returning `{allow_reserved?, value}`.
  defp unwrap_allow_reserved({:allow_reserved, value}), do: {true, value}
  defp unwrap_allow_reserved(value), do: {false, value}

  # Encode a query-parameter value, preserving RFC 3986 reserved characters when
  # the parameter declared `allowReserved: true`; otherwise percent-encode with
  # a %20 space.
  defp encode_query_value(value, true),
    do: PetstoreClient.ValueSerializer.encode_query_allowing_reserved(value)

  defp encode_query_value(value, false), do: encode_query_component(value)

  # Percent-encode a query key/value. URI.encode_www_form emits '+' for a space
  # (application/x-www-form-urlencoded rules), but RFC 3986 requires %20 in a
  # query component (a strict server reads '+' as a literal plus), so normalise
  # the space. A literal '+' is already %2B at this point. The form-urlencoded
  # body path keeps URI.encode_www_form's '+'. Matches the other SDKs.
  defp encode_query_component(value),
    do: value |> URI.encode_www_form() |> String.replace("+", "%20")

  defp serialize_body(nil, _content_type), do: nil

  # A format:binary body (tagged by the operation) is the caller's bytes, sent
  # verbatim under any selected content-type, application/json included.
  defp serialize_body({:raw_body, bytes}, _content_type), do: bytes

  defp serialize_body(body, "multipart/form-data"), do: body

  defp serialize_body(body, "application/octet-stream"), do: body

  defp serialize_body(body, "image/" <> _), do: body

  defp serialize_body(body, "text/plain"), do: to_string(body)

  # application/x-www-form-urlencoded: canonical form serialization (identical
  # across every SDK). Array fields emit one repeated key per element
  # (exploded, e.g. tags=a&tags=b - never tags=a,b or tags[]=); null/absent
  # fields are omitted entirely; URI.encode_www_form uses
  # application/x-www-form-urlencoded rules, so a space becomes '+'.
  defp serialize_body(body, "application/x-www-form-urlencoded")
       when is_map(body) or is_list(body) do
    body
    |> Enum.reject(fn {_k, v} -> is_nil(v) end)
    |> Enum.flat_map(&encode_form_pair/1)
    |> Enum.join("&")
  end

  defp serialize_body(body, _content_type), do: PetstoreClient.ObjectSerializer.serialize(body)

  defp encode_form_pair({key, values}) when is_list(values) do
    encoded_key = URI.encode_www_form(to_string(key))

    values
    |> Enum.reject(&is_nil/1)
    |> Enum.map(fn val ->
      ensure_form_scalar!(key, val)
      "#{encoded_key}=#{URI.encode_www_form(PetstoreClient.ObjectSerializer.stringify(val))}"
    end)
  end

  defp encode_form_pair({key, value}) do
    ensure_form_scalar!(key, value)

    [
      "#{URI.encode_www_form(to_string(key))}=#{URI.encode_www_form(PetstoreClient.ObjectSerializer.stringify(value))}"
    ]
  end

  # A model, map or array-of-objects has no defined form-urlencoded encoding
  # (the generator does not surface the OAS encoding style/explode), so it is
  # rejected rather than sent as the language's string conversion.
  defp ensure_form_scalar!(_key, %struct{})
       when struct in [DateTime, NaiveDateTime, Date, Time, Duration], do: :ok

  defp ensure_form_scalar!(key, value) when is_map(value) or is_list(value) do
    raise PetstoreClient.Errors.SerializationError,
      message: "form-urlencoded field #{key} must be a scalar or array of scalars"
  end

  defp ensure_form_scalar!(_key, _value), do: :ok
end

defmodule PetstoreClient.Auth.AllOfAuthenticator do
  @moduledoc """
  The credentials of every scheme one security requirement names together: the
  headers, query parameters and cookies of all of them are sent.
  """

  @behaviour PetstoreClient.Auth.Authenticator

  defstruct [:parts]

  @type t :: %__MODULE__{parts: [term()]}

  @doc """
  The composite of `parts`; one holding a token authenticator also hands the
  transport to it and drops its cached token on a 401.
  """
  @spec of([term()]) :: term()
  def of(parts) do
    if Enum.any?(parts, &token_authenticator?/1) do
      %{__struct__: PetstoreClient.Auth.AllOfTokenAuthenticator, parts: parts}
    else
      %__MODULE__{parts: parts}
    end
  end

  @doc false
  def token_authenticator?(%{__struct__: mod}) do
    Code.ensure_loaded?(mod) and
      (function_exported?(mod, :invalidate_access_token, 1) or
         function_exported?(mod, :set_api_client, 2))
  end

  def token_authenticator?(_other), do: false

  @impl true
  def host(%{parts: [first | _]}), do: call(first, :host)

  @impl true
  def auth_headers(%{parts: parts}), do: merge(parts, :auth_headers)

  @impl true
  def query_params(%{parts: parts}), do: merge(parts, :query_params)

  @impl true
  def cookie_params(%{parts: parts}), do: merge(parts, :cookie_params)

  @doc false
  def merge(parts, callback) do
    Enum.reduce(parts, %{}, fn part, merged -> Map.merge(merged, call(part, callback) || %{}) end)
  end

  @doc false
  def call(%{__struct__: mod} = part, callback) do
    if function_exported?(mod, callback, 1), do: apply(mod, callback, [part]), else: nil
  end

  def call(part, callback), do: Map.get(part, callback)
end

defmodule PetstoreClient.Auth.AllOfTokenAuthenticator do
  @moduledoc false

  @behaviour PetstoreClient.Auth.Authenticator

  alias PetstoreClient.Auth.AllOfAuthenticator

  defstruct [:parts]

  @impl true
  def host(self), do: AllOfAuthenticator.host(self)

  @impl true
  def auth_headers(self), do: AllOfAuthenticator.auth_headers(self)

  @impl true
  def query_params(self), do: AllOfAuthenticator.query_params(self)

  @impl true
  def cookie_params(self), do: AllOfAuthenticator.cookie_params(self)

  @doc false
  def set_api_client(%{parts: parts} = self, client) do
    %{self | parts: Enum.map(parts, &each_part(&1, :set_api_client, [client]))}
  end

  @doc false
  def invalidate_access_token(%{parts: parts}) do
    Enum.each(parts, &each_part(&1, :invalidate_access_token, []))
    :ok
  end

  @doc false
  def close(%{parts: parts}) do
    Enum.each(parts, &each_part(&1, :close, []))
    :ok
  end

  defp each_part(%{__struct__: mod} = part, function, args) do
    if function_exported?(mod, function, length(args) + 1) do
      result = apply(mod, function, [part | args])
      if function == :set_api_client, do: result, else: part
    else
      part
    end
  end

  defp each_part(part, _function, _args), do: part
end
